// ============ AI4SG collection settings: edit here ============
// The three LLM lines are rewritten by setup.sh from .env; you can also change them by hand.
const LLM_ENABLED = false;
const LLM_BASE_URL = 'https://api.openai.com/v1';
const LLM_MODEL = 'gpt-4o-mini';

return [{
  json: {
    runStartedAt: new Date().toISOString(),

    // GitHub repository search (https://docs.github.com/en/search-github/searching-on-github/searching-for-repositories)
    github: {
      perPage: 30,
      queries: [
        'topic:ai-for-social-good',
        'topic:ai4good',
        'topic:ai-for-good',
        'topic:social-good topic:machine-learning',
        'topic:humanitarian topic:machine-learning',
        'topic:global-health topic:machine-learning',
        '"AI for social good" in:description,readme',
      ],
    },

    // arXiv API query (https://info.arxiv.org/help/api/user-manual.html)
    arxiv: {
      maxResults: 60,
      query:
        '(abs:"social good" OR abs:"social impact" OR abs:"sustainable development goals" OR ' +
        'abs:"humanitarian" OR abs:"global health" OR abs:"low-resource settings" OR abs:"developing countries") ' +
        'AND (cat:cs.AI OR cat:cs.LG OR cat:cs.CL OR cat:cs.CV OR cat:cs.CY)',
    },

    // Google News RSS searches
    news: {
      queries: [
        '"AI for social good"',
        '"AI for good" project',
        'artificial intelligence nonprofit launches',
        'AI global health Africa',
        'AI smallholder farmers',
        'AI humanitarian response',
      ],
    },

    llm: {
      enabled: LLM_ENABLED,
      baseUrl: LLM_BASE_URL.replace(/\/+$/, ''),
      model: LLM_MODEL,
      maxItemsPerRun: 40, // cost guard: at most this many new items go to the LLM per run
    },
  },
}];

// One HTTP request per GitHub search query
const cfg = $input.first().json.github;
return cfg.queries.map((q) => ({
  json: {
    query: q,
    url:
      'https://api.github.com/search/repositories?q=' + encodeURIComponent(q) +
      '&sort=updated&order=desc&per_page=' + cfg.perPage,
  },
}));

// Flatten GitHub search responses into one item per repository (common schema)
const out = [];
for (const item of $input.all()) {
  const repos = Array.isArray(item.json.items) ? item.json.items : [];
  for (const r of repos) {
    if (r.fork || r.archived) continue;
    out.push({
      json: {
        id: 'github:' + r.id,
        source: 'github',
        source_id: String(r.id),
        title: r.full_name,
        url: r.html_url,
        description: (r.description || '').trim(),
        owner: r.owner && r.owner.login ? r.owner.login : null,
        owner_type: r.owner && r.owner.type ? r.owner.type : null,
        published_at: r.created_at || null,
        updated_at: r.pushed_at || r.updated_at || null,
        stars: r.stargazers_count ?? null,
        language: r.language || null,
        topics: Array.isArray(r.topics) ? r.topics : [],
        homepage: r.homepage || null,
      },
    });
  }
}
return out;

// Parse the arXiv Atom feed into one item per paper (common schema)
const decode = (s) =>
  (s || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'").replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ').trim();
const tag = (xml, name) => {
  const m = xml.match(new RegExp('<' + name + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + name + '>'));
  return m ? decode(m[1]) : '';
};

const out = [];
for (const item of $input.all()) {
  const xml = typeof item.json.data === 'string' ? item.json.data : '';
  const entries = xml.split('<entry>').slice(1).map((e) => e.split('</entry>')[0]);
  for (const e of entries) {
    const absUrl = tag(e, 'id');                       // e.g. http://arxiv.org/abs/2409.01234v2
    const arxivId = absUrl.replace(/^.*\/abs\//, '').replace(/v\d+$/, '');
    if (!arxivId) continue;
    const authors = [...e.matchAll(/<author>\s*<name>([\s\S]*?)<\/name>/g)].map((m) => decode(m[1]));
    const cats = [...e.matchAll(/<category[^>]*term="([^"]+)"/g)].map((m) => m[1]);
    out.push({
      json: {
        id: 'arxiv:' + arxivId,
        source: 'arxiv',
        source_id: arxivId,
        title: tag(e, 'title'),
        url: 'https://arxiv.org/abs/' + arxivId,
        description: tag(e, 'summary'),
        owner: authors.length > 3 ? authors.slice(0, 3).join(', ') + ' et al.' : authors.join(', '),
        published_at: tag(e, 'published') || null,
        stars: null,
        language: null,
        topics: cats,
      },
    });
  }
}
return out;

// One Google News RSS request per query
const cfg = $input.first().json.news;
return cfg.queries.map((q) => ({
  json: {
    query: q,
    url: 'https://news.google.com/rss/search?q=' + encodeURIComponent(q + ' when:30d') + '&hl=en-US&gl=US&ceid=US:en',
  },
}));

// Parse Google News RSS into one item per article (common schema)
const decode = (s) =>
  (s || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'").replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ').trim();
const tag = (xml, name) => {
  const m = xml.match(new RegExp('<' + name + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + name + '>'));
  return m ? m[1] : '';
};
// small stable hash so the id survives Google's long redirect URLs
const hash = (s) => {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return h.toString(36);
};

const out = [];
for (const item of $input.all()) {
  const xml = typeof item.json.data === 'string' ? item.json.data : '';
  const entries = xml.split('<item>').slice(1).map((e) => e.split('</item>')[0]);
  for (const e of entries) {
    let title = decode(tag(e, 'title'));
    const outlet = decode(tag(e, 'source'));
    if (outlet && title.endsWith(' - ' + outlet)) title = title.slice(0, -(outlet.length + 3));
    const link = decode(tag(e, 'link'));
    const guid = decode(tag(e, 'guid')) || link;
    if (!title || !link) continue;
    const pub = decode(tag(e, 'pubDate'));
    out.push({
      json: {
        id: 'news:' + hash(title.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()),
        source: 'news',
        source_id: guid,
        title,
        url: link,
        // Google News descriptions mostly repeat the headline; keep only extra text
        description: (() => {
          let d = decode(tag(e, 'description'));
          if (outlet && d.endsWith(outlet)) d = d.slice(0, -outlet.length).trim();
          if (d.startsWith(title)) d = d.slice(title.length).trim();
          return d;
        })(),
        owner: outlet || null,
        published_at: pub ? new Date(pub).toISOString() : null,
        stars: null,
        language: null,
        topics: [],
      },
    });
  }
}
return out;

// Dedupe across sources, apply the keyword classifier, and decide which items go to the LLM.
const cfg = $('Config').first().json;

// ---------- taxonomy: impact domain -> keywords + SDGs ----------
const DOMAINS = {
  global_health: { sdgs: [3], kw: ['health', 'medical', 'clinic', 'disease', 'malaria', 'tuberculosis', 'hiv', 'polio', 'vaccin', 'maternal', 'neonatal', 'newborn', 'diagnos', 'epidemi', 'pandemic', 'covid', 'malnutrition', 'nutrition', 'mental health', 'radiolog', 'patient', 'hospital'] },
  agriculture_food: { sdgs: [2], kw: ['agricultur', 'crop', 'farm', 'food security', 'famine', 'livestock', 'soil', 'harvest', 'smallholder', 'pest', 'yield'] },
  education: { sdgs: [4], kw: ['education', 'learning outcome', 'student', 'teacher', 'school', 'literacy', 'tutor', 'classroom'] },
  financial_inclusion: { sdgs: [1, 8], kw: ['financial inclusion', 'microfinance', 'mobile money', 'poverty', 'cash transfer', 'unbanked', 'credit scor', 'livelihood', 'informal econom'] },
  gender_equality: { sdgs: [5], kw: ['gender', 'women', 'girls', 'female', 'gender-based violence'] },
  water_sanitation: { sdgs: [6], kw: ['water', 'sanitation', 'hygiene', 'wash '] },
  climate_environment: { sdgs: [13, 15], kw: ['climate', 'carbon', 'emission', 'deforest', 'wildlife', 'biodiversity', 'conservation', 'ocean', 'air quality', 'pollution', 'renewable', 'energy access', 'poaching'] },
  disaster_humanitarian: { sdgs: [11, 16], kw: ['disaster', 'humanitarian', 'refugee', 'flood', 'earthquake', 'wildfire', 'crisis', 'emergency response', 'cyclone', 'drought', 'displacement'] },
  accessibility: { sdgs: [10], kw: ['accessib', 'disabilit', 'blind', 'visually impaired', 'deaf', 'sign language', 'assistive'] },
  governance_rights: { sdgs: [16], kw: ['misinformation', 'disinformation', 'human rights', 'justice', 'corruption', 'democracy', 'hate speech', 'public sector', 'civic'] },
};
const SOCIAL_KW = ['social good', 'for good', 'social impact', 'humanitarian', 'sustainable development', 'sdg', 'nonprofit', 'non-profit', 'ngo', 'low-resource', 'low resource', 'developing countr', 'global south', 'lmic', 'underserved', 'marginali', 'vulnerable', 'public good', 'philanthrop'];
const AI_KW = ['artificial intelligence', ' ai ', 'ai-', ' ai,', 'ai4', 'machine learning', 'deep learning', 'neural', 'llm', 'large language model', 'computer vision', 'nlp', 'natural language', 'data science', 'predictive model', 'transformer', 'reinforcement learning', 'chatbot', 'generative'];
const REGIONS = {
  'Sub-Saharan Africa': ['africa', 'kenya', 'nigeria', 'ethiopia', 'ghana', 'uganda', 'tanzania', 'rwanda', 'malawi', 'zambia', 'senegal', 'mozambique', 'zimbabwe', 'sahel'],
  'South Asia': ['india', 'bangladesh', 'pakistan', 'nepal', 'sri lanka', 'south asia'],
  'Southeast Asia': ['indonesia', 'philippines', 'vietnam', 'thailand', 'myanmar', 'cambodia', 'malaysia', 'singapore', 'southeast asia'],
  'Latin America': ['latin america', 'brazil', 'mexico', 'peru', 'colombia', 'chile', 'argentina', 'guatemala'],
  'Middle East & N. Africa': ['middle east', 'egypt', 'jordan', 'syria', 'yemen', 'morocco', 'lebanon'],
};

const count = (text, list) => list.reduce((n, k) => n + (text.includes(k) ? 1 : 0), 0);

function classify(it) {
  const text = (' ' + [it.title, it.description, (it.topics || []).join(' ')].join(' ') + ' ').toLowerCase();
  const scores = Object.entries(DOMAINS)
    .map(([name, d]) => [name, count(text, d.kw)])
    .sort((a, b) => b[1] - a[1]);
  const domain = scores[0][1] > 0 ? scores[0][0] : 'general';
  const sdgs = [...new Set(scores.filter(([, s]) => s > 0).slice(0, 2).flatMap(([n]) => DOMAINS[n].sdgs))].sort((a, b) => a - b);
  const region = Object.entries(REGIONS).find(([, kws]) => kws.some((k) => text.includes(k)))?.[0] || 'Global / unspecified';

  const social = count(text, SOCIAL_KW);
  const ai = count(text, AI_KW) + (it.source === 'arxiv' ? 1 : 0); // arXiv query is already restricted to AI categories
  const topicHit = (it.topics || []).some((t) => /ai-?for-?(social-)?good|ai4good|social-good/.test(t));
  let relevance = Math.min(1, 0.15 * social + 0.1 * ai + 0.1 * Math.min(scores[0][1], 3) + (topicHit ? 0.4 : 0));
  relevance = Math.round(relevance * 100) / 100;
  // relevant = tagged AI4SG on GitHub, or mentions AI together with a social-good term or an impact domain
  const is_relevant = topicHit || (ai > 0 && (social > 0 || scores[0][1] > 0));

  const owner = (it.owner || '').toLowerCase();
  let org_type = 'unknown';
  if (it.source === 'arxiv' || /universit|college|institute|lab\b|\.edu/.test(owner)) org_type = 'academic';
  else if (/foundation|\.org|ngo|unicef|who\b|undp|unhcr|red cross|nonprofit/.test(owner)) org_type = 'nonprofit';
  else if (/gov|ministry/.test(owner)) org_type = 'government';
  else if (it.source === 'github' && it.owner_type === 'User') org_type = 'community';

  const project_type = { github: 'open-source', arxiv: 'research', news: 'news' }[it.source] || 'other';
  const desc = (it.description || '').replace(/\s+/g, ' ').trim();
  const summary = desc.length > 280 ? desc.slice(0, 277) + '…' : desc;
  return { domain, sdgs, region, relevance, is_relevant, org_type, project_type, summary, analyzed_by: 'rules' };
}

// ---------- ids already in the database ----------
const known = new Map();
for (const row of $input.all()) if (row.json.id) known.set(row.json.id, row.json.analyzed_by);

// ---------- dedupe (id, then normalised title) ----------
const seenIds = new Set();
const seenTitles = new Set();
const items = [];
const perSource = {};
for (const { json: it } of $('Merge Sources').all()) {
  if (!it || !it.id || !it.title || !it.url) continue; // skips error items from failed requests
  const titleKey = it.title.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (seenIds.has(it.id) || seenTitles.has(titleKey)) continue;
  seenIds.add(it.id);
  seenTitles.add(titleKey);
  perSource[it.source] = (perSource[it.source] || 0) + 1;
  items.push({ ...it, ...classify(it), is_new: !known.has(it.id) });
}

// ---------- LLM selection: relevant-looking items not yet analysed by the LLM ----------
if (cfg.llm.enabled) {
  items
    .filter((it) => known.get(it.id) !== 'llm' && (it.is_relevant || it.relevance >= 0.2))
    .sort((a, b) => b.relevance - a.relevance)
    .slice(0, cfg.llm.maxItemsPerRun)
    .forEach((it) => { it.needs_llm = true; });
}
for (const it of items) it.needs_llm = !!it.needs_llm;

return items.map((json) => ({ json }));

// Build one OpenAI-compatible chat request per item
const cfg = $('Config').first().json.llm;
const SYSTEM = `You are an analyst cataloguing "AI for Social Good" projects for a philanthropic foundation.
Given one item (GitHub repo, arXiv paper, or news article), return ONLY a JSON object with these keys:
- "is_relevant": true only if the item describes an AI/ML/data-science project, tool, study or deployment whose primary aim is social benefit (health, poverty, food, education, climate, humanitarian, inclusion, rights...). Generic AI news, commercial products without a social mission, or courses/tutorials are false.
- "domain": one of ["global_health","agriculture_food","education","financial_inclusion","gender_equality","water_sanitation","climate_environment","disaster_humanitarian","accessibility","governance_rights","general"]
- "sdgs": array of UN SDG numbers (1-17), most relevant first, at most 3
- "region": one of ["Sub-Saharan Africa","South Asia","Southeast Asia","Latin America","Middle East & N. Africa","Global / unspecified","High-income countries"]
- "org_type": one of ["academic","nonprofit","company","government","community","unknown"]
- "summary": one English sentence (max 40 words): who does what with which AI technique, for whom
- "relevance": number 0-1, how central social impact is to the item`;

return $input.all().map(({ json: it }) => ({
  json: {
    ...it,
    llm_request: {
      model: cfg.model,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM },
        {
          role: 'user',
          content: JSON.stringify({
            source: it.source,
            title: it.title,
            description: (it.description || '').slice(0, 2500),
            owner: it.owner,
            topics: it.topics,
          }),
        },
      ],
    },
  },
}));

// Merge the LLM answer back onto each item; keep the keyword result when the call or parsing failed
const originals = $('LLM · Build Prompt').all();
const DOMAINS = ['global_health', 'agriculture_food', 'education', 'financial_inclusion', 'gender_equality', 'water_sanitation', 'climate_environment', 'disaster_humanitarian', 'accessibility', 'governance_rights', 'general'];
const ORG = ['academic', 'nonprofit', 'company', 'government', 'community', 'unknown'];

return $input.all().map((res, i) => {
  const { llm_request, ...it } = originals[i].json;
  try {
    let content = res.json.choices?.[0]?.message?.content;
    if (!content) throw new Error(res.json.error?.message || 'empty LLM response');
    content = content.replace(/^```(?:json)?\s*|\s*```$/g, '');
    const a = JSON.parse(content);
    return {
      json: {
        ...it,
        is_relevant: a.is_relevant === true,
        domain: DOMAINS.includes(a.domain) ? a.domain : it.domain,
        sdgs: Array.isArray(a.sdgs) ? a.sdgs.map(Number).filter((n) => n >= 1 && n <= 17).slice(0, 3) : it.sdgs,
        region: typeof a.region === 'string' && a.region ? a.region : it.region,
        org_type: ORG.includes(a.org_type) ? a.org_type : it.org_type,
        summary: typeof a.summary === 'string' && a.summary ? a.summary : it.summary,
        relevance: typeof a.relevance === 'number' ? Math.max(0, Math.min(1, a.relevance)) : it.relevance,
        analyzed_by: 'llm',
      },
    };
  } catch (e) {
    return { json: { ...it, llm_error: String(e.message || e) } };
  }
});
